package com.alkamel.lahmpos;

import android.Manifest;
import android.app.*;
import android.bluetooth.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.*;
import android.database.sqlite.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.OutputStream;
import java.text.DecimalFormat;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    final int BG=0xFF0B211D,PANEL=0xFF15352E,TEAL=0xFF57B89F,WHITE=0xFFF4F8F5,MUTED=0xFFADC3BA,GOLD=0xFFE6BD62,REQ=71;
    final String[] CATS={"اللحوم","الكبد","الوجبات","المخروج"},UNITS={"كيلو","نفر","قطعة"};
    Db db; LinearLayout root,body; DecimalFormat f=new DecimalFormat("#,##0.##"); String cat=CATS[0]; ArrayList<Line> cart=new ArrayList<>(); Handler h=new Handler(Looper.getMainLooper());
    public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);db=new Db(this);seed();home();}
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    android.graphics.drawable.GradientDrawable bg(int c){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(c);d.setCornerRadius(dp(14));return d;}
    LinearLayout col(){LinearLayout x=new LinearLayout(this);x.setOrientation(1);return x;}
    TextView t(String s,int z,int c,boolean b){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(c);x.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);x.setTypeface(null,b?1:0);x.setPadding(dp(8),dp(7),dp(8),dp(7));return x;}
    void shell(String sub){root=col();root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(BG);LinearLayout head=col();head.setPadding(dp(14),dp(10),dp(14),dp(5));head.addView(t("الكامل للحوم",23,WHITE,true));head.addView(t(sub,13,MUTED,false));root.addView(head);ScrollView sc=new ScrollView(this);body=col();body.setPadding(dp(12),dp(8),dp(12),dp(12));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    void add(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);body.addView(v,p);}
    EditText edit(String hint,boolean decimal){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextColor(WHITE);e.setHintTextColor(MUTED);e.setGravity(Gravity.RIGHT);e.setBackground(bg(PANEL));e.setPadding(dp(10),dp(5),dp(10),dp(5));e.setInputType(decimal?8194:2);return e;}
    Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(BG);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(TEAL));b.setOnClickListener(v->r.run());return b;}
    void seed(){if(db.count()==0){db.add("اللحوم","لحم غنم",6500,"كيلو");db.add("اللحوم","لحم بقري",4800,"كيلو");db.add("اللحوم","مفروم",6000,"كيلو");db.add("الكبد","كبدة",7000,"كيلو");db.add("الوجبات","وجبة لحم",2000,"نفر");db.add("الوجبات","وجبة كبدة",1800,"نفر");db.add("المخروج","شحم",2500,"كيلو");}}
    void home(){shell("نظام البيع وإدارة الملحمة");TextView s=t("مبيعات اليوم: "+f.format(db.today())+" ريال\nعدد الفواتير: "+db.countToday(),19,GOLD,true);s.setGravity(Gravity.CENTER);s.setBackground(bg(PANEL));add(s);for(String c:CATS)add(button("قسم "+c,()->sale(c)));add(button("إدارة الأصناف والأسعار",()->catalog()));add(button("سجل الفواتير وإعادة الطباعة",()->invoices()));add(button("اختيار الطابعة الحرارية",()->printer()));}
    void sale(String c){cat=c;cart.clear();shell("طلب جديد • "+c);ArrayList<Item> items=db.items(c);Spinner sp=new Spinner(this);ArrayList<String> names=new ArrayList<>();for(Item i:items)names.add(i.name+" | "+f.format(i.price)+" / "+i.unit);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));add(sp);EditText qty=edit(c.equals("الوجبات")?"الكمية (0.5 = نصف نفر)":"الوزن بالكيلو",true);add(qty);EditText price=edit("السعر",true);add(price);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int p,long id){if(p>=0&&p<items.size())price.setText(""+items.get(p).price);}});TextView total=t("لم تتم إضافة أصناف",16,GOLD,true);total.setBackground(bg(PANEL));add(total);
        add(button("إضافة للفاتورة",()->{try{int p=sp.getSelectedItemPosition();if(p<0||p>=items.size())throw new Exception("أضف أصنافاً لهذا القسم أولاً");double q=Double.parseDouble(qty.getText().toString()),pr=Double.parseDouble(price.getText().toString());if(q<=0||pr<0)throw new Exception();Item it=items.get(p);cart.add(new Line(it.name,it.unit,q,pr));double sum=0;StringBuilder b=new StringBuilder();for(Line l:cart){sum+=l.q*l.p;b.append(l.n).append("  ").append(l.q).append(" ").append(l.u).append("\n");}total.setText(b+"الإجمالي: "+f.format(sum)+" ريال");qty.setText("");}catch(Exception e){toast("أدخل الكمية والسعر بشكل صحيح، وتأكد من وجود صنف");}}));
        EditText customer=edit("اسم العميل (اختياري)",false);add(customer);add(button("حفظ الفاتورة ثم الطباعة",()->{if(cart.isEmpty()){toast("أضف صنفاً أولاً");return;}long id=db.save(customer.getText().toString(),cart);if(id<1){toast("فشل حفظ الفاتورة");return;}new AlertDialog.Builder(this).setTitle("تم حفظ الفاتورة رقم "+id).setMessage("الفاتورة محفوظة على الهاتف. هل تريد طباعتها؟").setNegativeButton("لاحقاً",(d,w)->home()).setPositiveButton("طباعة",(d,w)->print(id)).show();}));add(button("الرئيسية",()->home()));}
    void catalog(){shell("إدارة الأصناف والأسعار");Spinner cs=new Spinner(this);cs.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,CATS));add(cs);EditText n=edit("اسم الصنف",false),p=edit("السعر",true);add(n);add(p);Spinner us=new Spinner(this);us.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,UNITS));add(us);add(button("حفظ الصنف",()->{try{String name=n.getText().toString().trim();double val=Double.parseDouble(p.getText().toString());if(name.isEmpty()||val<0)throw new Exception();db.add((String)cs.getSelectedItem(),name,val,(String)us.getSelectedItem());toast("تم حفظ الصنف");catalog();}catch(Exception e){toast("تحقق من الاسم والسعر");}}));for(String c:CATS){add(t(c,18,GOLD,true));for(Item i:db.items(c))add(t(i.name+" — "+f.format(i.price)+" ريال / "+i.unit,15,WHITE,false));}add(button("الرئيسية",()->home()));}
    void invoices(){shell("سجل الفواتير");Cursor c=db.list();while(c.moveToNext()){long id=c.getLong(0);LinearLayout box=col();box.setPadding(dp(8),dp(6),dp(8),dp(6));box.setBackground(bg(PANEL));box.addView(t("فاتورة #"+id+" — "+f.format(c.getDouble(3))+" ريال",16,GOLD,true));box.addView(t(c.getString(1)+" • "+c.getString(2),12,MUTED,false));box.addView(button("عرض / إعادة طباعة",()->new AlertDialog.Builder(this).setTitle("فاتورة "+id).setMessage(db.text(id)).setNegativeButton("إغلاق",null).setPositiveButton("طباعة",(d,w)->print(id)).show()));add(box);}c.close();add(button("الرئيسية",()->home()));}
    void printer(){if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},REQ);return;}try{BluetoothAdapter a=BluetoothAdapter.getDefaultAdapter();if(a==null){toast("Bluetooth غير متوفر");return;}ArrayList<BluetoothDevice> ds=new ArrayList<>(a.getBondedDevices());if(ds.isEmpty()){toast("اقرن الطابعة من إعدادات الهاتف أولاً");return;}String[] labels=new String[ds.size()];for(int i=0;i<ds.size();i++)labels[i]=ds.get(i).getName()+" "+ds.get(i).getAddress();new AlertDialog.Builder(this).setTitle("اختر الطابعة المقترنة").setItems(labels,(d,w)->{getPreferences(0).edit().putString("printer",ds.get(w).getAddress()).apply();toast("تم اختيار الطابعة");}).show();}catch(Exception e){toast("تعذر فتح قائمة الطابعات");}}
    public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ&&g.length>0&&g[0]==0)printer();else if(r==REQ)toast("اسمح بالوصول إلى Bluetooth");}
    void print(long id){if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},REQ);return;}String addr=getPreferences(0).getString("printer",null);if(addr==null){printer();toast("اختر الطابعة ثم أعد محاولة الطباعة");return;}String data=db.text(id)+"\n\n\n";new Thread(()->{BluetoothSocket s=null;try{BluetoothDevice d=BluetoothAdapter.getDefaultAdapter().getRemoteDevice(addr);s=d.createRfcommSocketToServiceRecord(UUID.fromString("00001101-0000-1000-8000-00805F9B34FB"));s.connect();OutputStream o=s.getOutputStream();o.write(new byte[]{27,64});o.write(data.getBytes("UTF-8"));o.write(new byte[]{10,10,10,29,86,0});o.flush();h.post(()->toast("تم إرسال أمر الطباعة"));}catch(Exception e){h.post(()->toast("تعذرت الطباعة؛ الفاتورة ما زالت محفوظة ويمكن إعادة المحاولة"));}finally{try{if(s!=null)s.close();}catch(Exception ignored){}}}).start();}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    static class Item{String name,unit;double price;Item(String n,double p,String u){name=n;price=p;unit=u;}}
    static class Line{String n,u;double q,p;Line(String a,String b,double c,double d){n=a;u=b;q=c;p=d;}}
    static class Db extends SQLiteOpenHelper{
        Db(Context c){super(c,"lahmpos_v2.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE catalog(id INTEGER PRIMARY KEY AUTOINCREMENT,category TEXT,name TEXT,price REAL,unit TEXT)");d.execSQL("CREATE TABLE invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,created TEXT,customer TEXT,total REAL)");d.execSQL("CREATE TABLE lines(id INTEGER PRIMARY KEY AUTOINCREMENT,invoice_id INTEGER,name TEXT,unit TEXT,qty REAL,price REAL,total REAL)");}public void onUpgrade(SQLiteDatabase d,int o,int n){}
        int count(){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM catalog",null);c.moveToFirst();int n=c.getInt(0);c.close();return n;}
        void add(String c,String n,double p,String u){ContentValues v=new ContentValues();v.put("category",c);v.put("name",n);v.put("price",p);v.put("unit",u);getWritableDatabase().insert("catalog",null,v);}
        ArrayList<Item> items(String cat){ArrayList<Item>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT name,price,unit FROM catalog WHERE category=? ORDER BY name",new String[]{cat});while(c.moveToNext())a.add(new Item(c.getString(0),c.getDouble(1),c.getString(2)));c.close();return a;}
        long save(String customer,ArrayList<Line> lines){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{double sum=0;for(Line l:lines)sum+=l.q*l.p;String date=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).format(new Date());ContentValues v=new ContentValues();v.put("created",date);v.put("customer",customer);v.put("total",sum);long id=d.insertOrThrow("invoices",null,v);for(Line l:lines){ContentValues x=new ContentValues();x.put("invoice_id",id);x.put("name",l.n);x.put("unit",l.u);x.put("qty",l.q);x.put("price",l.p);x.put("total",l.q*l.p);d.insertOrThrow("lines",null,x);}d.setTransactionSuccessful();return id;}catch(Exception e){return -1;}finally{d.endTransaction();}}
        double today(){String day=new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date());Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(total),0) FROM invoices WHERE substr(created,1,10)=?",new String[]{day});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}
        int countToday(){String day=new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date());Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM invoices WHERE substr(created,1,10)=?",new String[]{day});c.moveToFirst();int x=c.getInt(0);c.close();return x;}
        Cursor list(){return getReadableDatabase().rawQuery("SELECT id,created,customer,total FROM invoices ORDER BY id DESC",null);}
        String text(long id){StringBuilder b=new StringBuilder("الكامل للحوم\nفاتورة رقم: "+id+"\n");Cursor c=getReadableDatabase().rawQuery("SELECT created,customer,total FROM invoices WHERE id=?",new String[]{""+id});double total=0;if(c.moveToFirst()){b.append("التاريخ: ").append(c.getString(0)).append("\nالعميل: ").append(c.getString(1)).append("\n-----------------------\n");total=c.getDouble(2);}c.close();c=getReadableDatabase().rawQuery("SELECT name,qty,unit,price,total FROM lines WHERE invoice_id=?",new String[]{""+id});while(c.moveToNext())b.append(c.getString(0)).append("\n").append(c.getDouble(1)).append(" ").append(c.getString(2)).append(" × ").append(c.getDouble(3)).append(" = ").append(c.getDouble(4)).append(" ريال\n");c.close();return b.append("-----------------------\nالإجمالي: ").append(total).append(" ريال\nشكراً لزيارتكم").toString();}
    }
}